"},{"signature":"private.ifo_usage_valid(jsonb)","sha256":"eaad99f9a4064320c648f12452b1f9a4007d872431c21e98a7eded66b4e9018c","language":"plpgsql","definer":false,"volatility":"i","strict":false,"setof":false,"acl":"private","resultType":"boolean"},{"signature":"private.ifo_sha(text)","sha256":"e5250af925064180a23863a27e15497294527ddf301b92306095e2647b6ed52f","language":"plpgsql","definer":false,"volatility":"i","strict":false,"setof":false,"acl":"private","resultType":"text"},{"signature":"private.ifo_stamp(timestamptz)","sha256":"4167f675c819dfaa75a88253c396f3822fbaf6542f7020c4558c80c8b1b8b4e0","language":"plpgsql","definer":false,"volatility":"s","strict":false,"setof":false,"acl":"private","resultType":"text"},{"signature":"private.owned_ai_disposition_guard()","sha256":"b489c10cedcdc457a444521019fee37375ed3236ebfe5a1eb749b280b1acaa56","language":"plpgsql","definer":false,"volatility":"v","strict":false,"setof":false,"acl":"private","resultType":"trigger"},{"signature":"private.owned_ai_disposition_catalogue()","sha256":"fec13284378f343e144c83c2213e16954b3ea1f52ed7fcd0c3fde6a3f2524f52","language":"sql","definer":false,"volatility":"s","strict":false,"setof":false,"acl":"private","resultType":"jsonb"},{"signature":"private.retire_initial_feedback_publications(uuid,uuid,uuid,uuid)","sha256":"d066dfb3459d527b551ab81a564f85e896220e8b8f88749d21e378bd2b84cce0","language":"plpgsql","definer":false,"volatility":"v","strict":false,"setof":false,"acl":"private","resultType":"void"}]$legacy_functions$::jsonb;
begin
