   or p.prorettype<>to_regtype(item->>'resultType') or p.prolang<>(select oid from pg_catalog.pg_language where lanname=item->>'language')
   or p.proconfig is distinct from array['search_path=""'] or private.ifo_sha(p.prosrc)<>item->>'sha256' then return false;end if;
  if exists(select 1 from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where a.grantee<>p.proowner
    and (item->>'acl'='private' or a.grantee<>service_oid or a.privilege_type<>'EXECUTE' or a.is_grantable)) then return false;end if;
  foreach role_name in array array['anon','authenticated'] loop if has_function_privilege(role_name,p.oid,'EXECUTE') then return false;end if;end loop;
  if item->>'acl'='private' and has_function_privilege('service_role',p.oid,'EXECUTE') then return false;end if;
  if item->>'acl' in ('service','metadata') and not has_function_privilege('service_role',p.oid,'EXECUTE') then return false;end if;
 end loop;
 select * into p from pg_catalog.pg_proc where oid=to_regprocedure('private.owned_legacy_ai_usage_ready()');
 if not found or p.proowner<>owner_oid or p.prokind<>'f' or p.prosecdef or p.proretset or p.proisstrict or p.provolatile<>'s' or p.prorettype<>'boolean'::regtype
   or p.proconfig is distinct from array['search_path=""'] or exists(select 1 from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where a.grantee<>p.proowner) then return false;end if;
 foreach role_name in array array['anon','authenticated','service_role'] loop if has_function_privilege(role_name,p.oid,'EXECUTE') then return false;end if;end loop;
 for rel in select * from pg_catalog.pg_class where oid in ('private.owned_legacy_ai_usage_retirements'::regclass,'private.owned_legacy_ai_usage_catalogue_seal'::regclass) loop
  if rel.relkind<>'r' or rel.relowner<>owner_oid or not rel.relrowsecurity or rel.relforcerowsecurity
    or exists(select 1 from pg_catalog.pg_policy where polrelid=rel.oid)
    or exists(select 1 from aclexplode(coalesce(rel.relacl,acldefault('r',rel.relowner))) a where a.grantee<>rel.relowner)
    or exists(select 1 from pg_catalog.pg_attribute where attrelid=rel.oid and attnum>0 and not attisdropped and (atthasdef or attidentity<>'' or attgenerated<>''))
    or exists(select 1 from pg_catalog.pg_constraint where conrelid=rel.oid and contype='f') then return false;end if;
  foreach role_name in array array['anon','authenticated','service_role'] loop if has_table_privilege(role_name,rel.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
    or has_any_column_privilege(role_name,rel.oid,'SELECT,INSERT,UPDATE,REFERENCES') then return false;end if;end loop;
 end loop;
 -- Parent locks rely on the actual validated cascade FKs, never a learned missing key.
 if not exists(select 1 from pg_catalog.pg_constraint k where k.conrelid='public.analysis_ai_runs'::regclass and k.contype='p' and k.convalidated
   and (select array_agg(a.attname::text order by v.ordinality) from unnest(k.conkey) with ordinality v(n,ordinality)
     join pg_catalog.pg_attribute a on a.attrelid=k.conrelid and a.attnum=v.n)=array['id']) then return false;end if;
 for item in select value from jsonb_array_elements($legacy_source_fks$[
  {"child":"public.analysis_ai_runs","parent":"public.analyses","column":"analysis_id"},
  {"child":"public.analyses","parent":"public.resume_versions","column":"resume_version_id"},
  {"child":"public.resume_versions","parent":"public.resumes","column":"resume_id"}
 ]$legacy_source_fks$::jsonb) loop
  if not exists(select 1 from pg_catalog.pg_constraint k where k.conrelid=to_regclass(item->>'child') and k.confrelid=to_regclass(item->>'parent')
    and k.contype='f' and k.convalidated and not k.condeferrable and k.confdeltype='c'
    and (select array_agg(a.attname::text order by v.ordinality) from unnest(k.conkey) with ordinality v(n,ordinality)
      join pg_catalog.pg_attribute a on a.attrelid=k.conrelid and a.attnum=v.n)=array[item->>'column']
    and (select array_agg(a.attname::text order by v.ordinality) from unnest(k.confkey) with ordinality v(n,ordinality)
      join pg_catalog.pg_attribute a on a.attrelid=k.confrelid and a.attnum=v.n)=array['id']
    and exists(select 1 from pg_catalog.pg_trigger g where g.tgconstraint=k.oid and g.tgrelid=k.conrelid)
    and exists(select 1 from pg_catalog.pg_trigger g where g.tgconstraint=k.oid and g.tgrelid=k.confrelid)
    and not exists(select 1 from pg_catalog.pg_trigger g where g.tgconstraint=k.oid and g.tgenabled<>'O')) then return false;end if;
 end loop;
 -- Actual source INT counters must retain their original NOT NULL and >=0 CHECK.
 foreach column_name in array array['input_tokens','output_tokens'] loop
  if not exists(select 1 from pg_catalog.pg_attribute a where a.attrelid='public.analysis_ai_runs'::regclass and a.attname=column_name
    and a.atttypid='integer'::regtype and a.attnotnull and not a.attisdropped)
   or not exists(select 1 from pg_catalog.pg_constraint k where k.conrelid='public.analysis_ai_runs'::regclass and k.contype='c' and k.convalidated
    and regexp_replace(pg_get_expr(k.conbin,k.conrelid),'[[:space:]()"]','','g')=column_name||'>=0') then return false;end if;
 end loop;
 if private.owned_ai_disposition_catalogue() is distinct from (select catalogue from private.owned_ai_disposition_catalogue_seal where singleton)
   then return false;end if;
 if (select count(*) from private.owned_legacy_ai_usage_catalogue_seal)<>1 or not exists(select 1 from private.owned_legacy_ai_usage_catalogue_seal where singleton)
   or private.ifo_sha(private.owned_legacy_ai_usage_catalogue()::text) is distinct from (select catalogue_sha256 from private.owned_legacy_ai_usage_catalogue_seal where singleton) then return false;end if;
 if not exists(select 1 from pg_catalog.pg_trigger where tgrelid='private.owned_legacy_ai_usage_retirements'::regclass and tgname='owned_legacy_ai_usage_guard'
   and not tgisinternal and tgenabled='O' and tgfoid=to_regprocedure('private.owned_legacy_ai_usage_guard()') and tgtype=31 and tgnargs=0 and tgqual is null and tgconstraint=0)
  or not exists(select 1 from pg_catalog.pg_trigger where tgrelid='private.owned_legacy_ai_usage_catalogue_seal'::regclass and tgname='owned_legacy_ai_usage_seal_closed'
   and not tgisinternal and tgenabled='O' and tgfoid=to_regprocedure('private.owned_legacy_ai_usage_seal_closed()') and tgtype=31 and tgnargs=0 and tgqual is null and tgconstraint=0)
  or (select count(*) from pg_catalog.pg_trigger where tgrelid='private.owned_legacy_ai_usage_catalogue_seal'::regclass and not tgisinternal)<>1 then return false;end if;
 return true;
exception when others then return false;
end;
$legacy_ready$;

do $usage_forward$
declare item jsonb;p pg_catalog.pg_proc%rowtype;source text;statements text[]:=array[]::text[];ddl text;
 manifest jsonb:=$usage_patches$[{"signature":"public.prepare_deletion_request(uuid,text)","before":"c218ea717c679b84fdc826b6a493b38937061c9d6b279a7b0e5d8ed53ce6e146","after":"9f6e5fce4165a54d30007c73f48424ea70d7e650fda719b8c68f73fe009cd5fb","old":"\ndeclare\n  request_row public.data_requests%rowtype;\n  storage_objects jsonb;\n  first_at timestamptz;\nbegin\n  select * into request_row\n  from public.data_requests\n  where id = p_request_id\n    and kind = 'deletion'\n    and status = 'processing'\n    and lease_owner = p_worker_id\n  for update;\n  if not found then\n    raise exception 'privacy deletion request is not owned' using errcode = '42501';\n  end if;\n\n  if not private.try_lock_candidate_owners(array[request_row.user_id]) then raise exception 'PRIVACY_OWNER_BUSY' using errcode='55P03';end if;\n  select plan.storage_objects,plan.created_at into storage_objects,first_at\n  from private.privacy_deletion_plans plan\n  where plan.request_id = request_row.id;\n\n  if not found then\n    select coalesce(jsonb_agg(jsonb_build_object(\n      'storageKey', storage_key,\n      'checksum', checksum,\n      'bytes', bytes\n    )), '[]'::jsonb)\n    into storage_objects\n    from public.resume_versions\n    where owner_id = request_row.user_id;\n\n    if not exists(select 1 from private.owned_ai_deletion_dispositions where owner_id=request_row.user_id)\n      and exists(select 1 from public.data_requests d join public.privacy_request_steps s on s.request_id=d.id\n        where d.user_id=request_row.user_id and d.kind='deletion' and s.step_key='database' and s.status='completed')\n      then raise exception 'OWNED_AI_DISPOSITION_HISTORICAL_REPAIR' using errcode='23514';end if;\n    first_at:=clock_timestamp();\n    insert into private.privacy_deletion_plans (request_id, storage_objects,created_at)\n    values (request_row.id, storage_objects,first_at);\n  end if;\n\n  -- Candidate rows and the durable object plan commit atomically. A retry can\n  -- therefore continue deleting the same objects after database rows are gone.\n  insert into private.owned_ai_deletion_dispositions(owner_id,first_request_id,prepared_at,expires_at,phase)\n    values(request_row.user_id,request_row.id,first_at,first_at+interval '720 hours','prepared') on conflict(owner_id) do nothing;\n  perform private.capture_owned_ai_operation_dispositions(request_row.user_id,null,request_row.id,null);\n  perform private.retire_initial_feedback_publications(request_row.user_id,null,request_row.id,null);\n  delete from public.analyses where owner_id = request_row.user_id;\n  delete from public.jobs where owner_id = request_row.user_id;\n  delete from public.resumes where owner_id = request_row.user_id;\n  delete from public.consents where user_id = request_row.user_id;\n  delete from public.memberships where user_id = request_row.user_id;\n  delete from public.profiles where id = request_row.user_id;\n\n  update public.privacy_request_steps\n  set status = 'completed', completed_at = timezone('utc', now())\n  where request_id = request_row.id and step_key = 'database';\n\n  return jsonb_build_object(\n    'storageObjects', storage_objects,\n    'databaseDeletedAt', timezone('utc', now())\n  );\nend;\n","new":"\ndeclare\n  request_row public.data_requests%rowtype;\n  storage_objects jsonb;\n  first_at timestamptz;\nbegin\n  select * into request_row\n  from public.data_requests\n  where id = p_request_id\n    and kind = 'deletion'\n    and status = 'processing'\n    and lease_owner = p_worker_id\n  for update;\n  if not found then\n    raise exception 'privacy deletion request is not owned' using errcode = '42501';\n  end if;\n\n  if not private.try_lock_candidate_owners(array[request_row.user_id]) then raise exception 'PRIVACY_OWNER_BUSY' using errcode='55P03';end if;\n  select plan.storage_objects,plan.created_at into storage_objects,first_at\n  from private.privacy_deletion_plans plan\n  where plan.request_id = request_row.id;\n\n  if not found then\n    select coalesce(jsonb_agg(jsonb_build_object(\n      'storageKey', storage_key,\n      'checksum', checksum,\n      'bytes', bytes\n    )), '[]'::jsonb)\n    into storage_objects\n    from public.resume_versions\n    where owner_id = request_row.user_id;\n\n    if not exists(select 1 from private.owned_ai_deletion_dispositions where owner_id=request_row.user_id)\n      and exists(select 1 from public.data_requests d join public.privacy_request_steps s on s.request_id=d.id\n        where d.user_id=request_row.user_id and d.kind='deletion' and s.step_key='database' and s.status='completed')\n      then raise exception 'OWNED_AI_DISPOSITION_HISTORICAL_REPAIR' using errcode='23514';end if;\n    first_at:=clock_timestamp();\n    insert into private.privacy_deletion_plans (request_id, storage_objects,created_at)\n    values (request_row.id, storage_objects,first_at);\n  end if;\n\n  -- Candidate rows and the durable object plan commit atomically. A retry can\n  -- therefore continue deleting the same objects after database rows are gone.\n  insert into private.owned_ai_deletion_dispositions(owner_id,first_request_id,prepared_at,expires_at,phase)\n    values(request_row.user_id,request_row.id,first_at,first_at+interval '720 hours','prepared') on conflict(owner_id) do nothing;\n  perform private.capture_owned_ai_operation_dispositions(request_row.user_id,null,request_row.id,null);\n  perform private.capture_owned_legacy_ai_usage(request_row.user_id,null,request_row.id,null);\n  perform private.retire_initial_feedback_publications(request_row.user_id,null,request_row.id,null);\n  delete from public.analyses where owner_id = request_row.user_id;\n  delete from public.jobs where owner_id = request_row.user_id;\n  delete from public.resumes where owner_id = request_row.user_id;\n  delete from public.consents where user_id = request_row.user_id;\n  delete from public.memberships where user_id = request_row.user_id;\n  delete from public.profiles where id = request_row.user_id;\n\n  update public.privacy_request_steps\n  set status = 'completed', completed_at = timezone('utc', now())\n  where request_id = request_row.id and step_key = 'database';\n\n  return jsonb_build_object(\n    'storageObjects', storage_objects,\n    'databaseDeletedAt', timezone('utc', now())\n  );\nend;\n","setof":false},{"signature":"public.complete_retention_item(uuid)","before":"89fddcba7c5d3ee9f745e9f9afdff7aa7eeedce59237805f7864e495a49f4898","after":"ee73fa96bea622c7e0e6ed21318488646afbf754406eefd55574d1e087e69a2a","old":"declare selected private.retention_items%rowtype;item_row private.retention_items%rowtype;root_row public.resumes%rowtype;\nbegin\n select * into selected from private.retention_items where id=p_item_id;\n if not found then return false;end if;\n if selected.status='deleted' then return true;end if;\n if private.owned_ai_disposition_ready() is not true then raise exception 'RETENTION_SOURCE_UNAVAILABLE' using errcode='23514';end if;\n if not private.try_lock_candidate_owners(array[selected.owner_id]) then raise exception 'PRIVACY_OWNER_BUSY' using errcode='55P03';end if;\n -- Re-read terminal state after owner acquisition BEFORE requiring a parent:\n -- another completion may have committed both deletion and parent cascade.\n select * into item_row from private.retention_items where id=p_item_id for update skip locked;\n if not found then\n  if exists(select 1 from private.retention_items where id=p_item_id) then raise exception 'RETENTION_ITEM_BUSY' using errcode='55P03';end if;\n  return false;\n end if;\n if (item_row.owner_id,item_row.resume_id,item_row.storage_key) is distinct from (selected.owner_id,selected.resume_id,selected.storage_key)\n  then raise exception 'RETENTION_ITEM_IDENTITY_CONFLICT' using errcode='23514';end if;\n if item_row.status='deleted' then return true;end if;\n root_row:=private.r17_lock_root(item_row.owner_id,item_row.resume_id);\n if root_row.status<>'deleted' or not exists(select 1 from public.resume_versions v where v.resume_id=root_row.id and v.owner_id=root_row.owner_id\n   and v.organization_id=root_row.organization_id and v.storage_key=item_row.storage_key\n   and v.storage_key=private.r17_storage_key(v.organization_id,v.resume_id,v.id))\n  then raise exception 'RETENTION_PARENT_REPAIR_REQUIRED' using errcode='23514';end if;\n update private.retention_items set status='deleted',completed_at=clock_timestamp(),last_error_code=null where id=p_item_id and status in ('queued','failed');\n if not found then raise exception 'RETENTION_ITEM_STATE' using errcode='23514';end if;\n -- Missing/unenrolled actual versions prevent BOTH publication retirement and\n -- parent cascade, even when every recorded work item is already deleted.\n if private.r17_root_covered(root_row.owner_id,root_row.id,root_row.organization_id) is true then\n  perform private.retire_initial_feedback_publications(root_row.owner_id,root_row.id,null,item_row.id);\n  -- Recheck coverage under the same owner/root/source locks immediately before DELETE.\n  delete from public.resumes r where r.id=root_row.id and r.owner_id=root_row.owner_id and r.status='deleted'\n    and private.r17_root_covered(root_row.owner_id,root_row.id,root_row.organization_id) is true;\n  if not found then raise exception 'RETENTION_COVERAGE_CHANGED' using errcode='23514';end if;\n end if;\n return true;\nend;\n","new":"declare selected private.retention_items%rowtype;item_row private.retention_items%rowtype;root_row public.resumes%rowtype;\nbegin\n select * into selected from private.retention_items where id=p_item_id;\n if not found then return false;end if;\n if selected.status='deleted' then return true;end if;\n if private.owned_ai_disposition_ready() is not true then raise exception 'RETENTION_SOURCE_UNAVAILABLE' using errcode='23514';end if;\n if not private.try_lock_candidate_owners(array[selected.owner_id]) then raise exception 'PRIVACY_OWNER_BUSY' using errcode='55P03';end if;\n -- Re-read terminal state after owner acquisition BEFORE requiring a parent:\n -- another completion may have committed both deletion and parent cascade.\n select * into item_row from private.retention_items where id=p_item_id for update skip locked;\n if not found then\n  if exists(select 1 from private.retention_items where id=p_item_id) then raise exception 'RETENTION_ITEM_BUSY' using errcode='55P03';end if;\n  return false;\n end if;\n if (item_row.owner_id,item_row.resume_id,item_row.storage_key) is distinct from (selected.owner_id,selected.resume_id,selected.storage_key)\n  then raise exception 'RETENTION_ITEM_IDENTITY_CONFLICT' using errcode='23514';end if;\n if item_row.status='deleted' then return true;end if;\n root_row:=private.r17_lock_root(item_row.owner_id,item_row.resume_id);\n if root_row.status<>'deleted' or not exists(select 1 from public.resume_versions v where v.resume_id=root_row.id and v.owner_id=root_row.owner_id\n   and v.organization_id=root_row.organization_id and v.storage_key=item_row.storage_key\n   and v.storage_key=private.r17_storage_key(v.organization_id,v.resume_id,v.id))\n  then raise exception 'RETENTION_PARENT_REPAIR_REQUIRED' using errcode='23514';end if;\n update private.retention_items set status='deleted',completed_at=clock_timestamp(),last_error_code=null where id=p_item_id and status in ('queued','failed');\n if not found then raise exception 'RETENTION_ITEM_STATE' using errcode='23514';end if;\n -- Missing/unenrolled actual versions prevent BOTH publication retirement and\n -- parent cascade, even when every recorded work item is already deleted.\n if private.r17_root_covered(root_row.owner_id,root_row.id,root_row.organization_id) is true then\n  perform private.capture_owned_legacy_ai_usage(root_row.owner_id,root_row.id,null,item_row.id);\n  perform private.retire_initial_feedback_publications(root_row.owner_id,root_row.id,null,item_row.id);\n  -- Recheck coverage under the same owner/root/source locks immediately before DELETE.\n  delete from public.resumes r where r.id=root_row.id and r.owner_id=root_row.owner_id and r.status='deleted'\n    and private.r17_root_covered(root_row.owner_id,root_row.id,root_row.organization_id) is true;\n  if not found then raise exception 'RETENTION_COVERAGE_CHANGED' using errcode='23514';end if;\n end if;\n return true;\nend;\n","setof":false},{"signature":"public.get_organization_ai_tokens_used(uuid,timestamptz)","before":"3224c404b91060e902b7468e02509d6a63371ab39e216f21c7b39c42ddef7201","after":"148f1822c223d95e7b6e4ffc8854e89f3699e3c61de7ac31b6b3ffeaeaa0cafc","old":"\n  select coalesce(sum(input_tokens + output_tokens), 0)::bigint\n  from public.analysis_ai_runs\n  where organization_id = p_organization_id\n    and created_at >= p_since;\n","new":"\n select private.read_preserved_organization_ai_tokens(p_organization_id,p_since);\n","setof":false},{"signature":"public.read_initial_feedback_usage(uuid,uuid)","before":"9564c709cea106d8999c61e4db14ce45c40c41eacd23ce54f7fa1ea5c234c223","after":"3ced80cc4289760a1e4b88defefe7f330374968fcc96592dc775a116b615ddc3","old":"\ndeclare a public.analyses%rowtype;period_start date;period_end date;\n  legacy_tokens numeric;canonical_tokens numeric;feedback_tokens numeric;unknown_claims bigint;\n  values_valid boolean;links_valid boolean;total_tokens numeric;\nbegin\n  if private.initial_feedback_ready() is not true then perform private.ifo_fail('unavailable');end if;\n  a:=private.owned_ai_usage_owner(p_user_id,p_analysis_id);\n  period_start:=date_trunc('month',clock_timestamp() at time zone 'UTC')::date;\n  period_end:=(period_start+interval '1 month')::date;\n  -- One statement snapshot; link validation/exclusion has NO month predicate.\n  -- Only the three disjoint components below select their respective month.\n  with canonical_scope as materialized (\n    select x.owner_id,x.organization_id,x.analysis_id,x.operation_id,x.run_id,x.claimed_at,nullif(x.usage,'null'::jsonb) usage,\n      x.binding_sha256,x.policy->>'model' model,x.policy->>'promptVersion' prompt_version\n    from private.canonical_rewrite_operations x where x.organization_id=a.organization_id\n    union\n    select x.owner_id,x.organization_id,x.analysis_id,x.operation_id,x.run_id,x.claimed_at,nullif(x.usage,'null'::jsonb),\n      x.binding_sha256,x.policy->>'model',x.policy->>'promptVersion'\n    from private.canonical_rewrite_operations x join public.analysis_ai_runs r on r.id=x.run_id where r.organization_id=a.organization_id\n  ), feedback_attempts as materialized (\n    select t.attempt_id,t.operation_id,t.claimed_at,nullif(t.usage,'null'::jsonb) usage,o.owner_id,o.organization_id,o.analysis_id,\n      o.binding_sha256,o.binding->'policy'->>'model' model,o.binding->'policy'->>'promptVersion' prompt_version\n    from private.initial_feedback_attempts t join private.initial_feedback_operations o on o.operation_id=t.operation_id\n    where o.organization_id=a.organization_id\n  ), retirement_scope as materialized (\n    select s.* from private.initial_feedback_content_retirements s where s.organization_id=a.organization_id\n    union select s.* from private.initial_feedback_content_retirements s join private.initial_feedback_operations o on o.operation_id=s.operation_id where o.organization_id=a.organization_id\n    union select s.* from private.initial_feedback_content_retirements s join public.analysis_ai_runs r on r.id=s.run_id where r.organization_id=a.organization_id\n  ), publication_scope as materialized (\n    select p.id,p.operation_id,p.attempt_id,p.analysis_id,p.owner_id,p.organization_id,p.run_id,p.state,p.binding_sha256\n    from private.initial_feedback_publications p where p.organization_id=a.organization_id\n    union\n    select p.id,p.operation_id,p.attempt_id,p.analysis_id,p.owner_id,p.organization_id,p.run_id,p.state,p.binding_sha256\n    from private.initial_feedback_publications p join private.initial_feedback_operations o on o.operation_id=p.operation_id where o.organization_id=a.organization_id\n    union\n    select p.id,p.operation_id,p.attempt_id,p.analysis_id,p.owner_id,p.organization_id,p.run_id,p.state,p.binding_sha256\n    from private.initial_feedback_publications p join public.analysis_ai_runs r on r.id=p.run_id where r.organization_id=a.organization_id\n    union\n    select s.publication_id,s.operation_id,s.attempt_id,s.analysis_id,s.owner_id,s.organization_id,s.run_id,s.publication_state,s.binding_sha256\n    from retirement_scope s\n  ), links as materialized (\n    -- Retained pre-compatibility A12 legacy runs are authoritative links too.\n    select r.id run_id,coalesce(x.organization_id=a.organization_id and x.claimed_at is not null and isfinite(x.claimed_at)\n      and x.usage is not null and private.ifo_usage_valid(x.usage)\n      and (r.owner_id,r.organization_id,r.analysis_id)=(x.owner_id,x.organization_id,x.analysis_id)\n      and r.provider='openai' and r.model_id=x.model and r.prompt_version=x.prompt_version and r.input_hash=x.binding_sha256\n      and r.input_tokens>=0 and r.output_tokens>=0\n      and r.input_tokens::text=x.usage->>'inputTokens' and r.output_tokens::text=x.usage->>'outputTokens',false) valid\n    from canonical_scope x join public.analysis_ai_runs r on r.id=x.run_id\n    union all\n    select p.run_id,coalesce(p.organization_id=a.organization_id and p.state='assessed'\n      and o.operation_id=p.operation_id and o.publication_id=p.id and o.state='published'\n      and t.attempt_id=p.attempt_id and t.operation_id=o.operation_id\n      and (p.owner_id,p.organization_id,p.analysis_id)=(o.owner_id,o.organization_id,o.analysis_id)\n      and p.binding_sha256=o.binding_sha256 and t.claimed_at is not null and isfinite(t.claimed_at)\n      and nullif(t.usage,'null'::jsonb) is not null and private.ifo_usage_valid(t.usage)\n      and (r.owner_id,r.organization_id,r.analysis_id)=(p.owner_id,p.organization_id,p.analysis_id)\n      and r.provider='openai' and r.model_id=o.binding->'policy'->>'model' and r.prompt_version=o.binding->'policy'->>'promptVersion'\n      and r.input_hash=o.binding_sha256 and r.input_tokens>=0 and r.output_tokens>=0\n      and r.input_tokens::text=t.usage->>'inputTokens' and r.output_tokens::text=t.usage->>'outputTokens',false)\n    from publication_scope p left join private.initial_feedback_operations o on o.operation_id=p.operation_id\n      left join private.initial_feedback_attempts t on t.attempt_id=p.attempt_id\n      left join public.analysis_ai_runs r on r.id=p.run_id where p.run_id is not null\n      and (r.id is not null or not exists(select 1 from retirement_scope s where s.publication_id=p.id and s.run_id=p.run_id))\n  ), integrity as (\n    select not exists(select 1 from links where not valid)\n      and not exists(select 1 from links group by run_id having count(*)>1)\n      and not exists(select 1 from retirement_scope s left join private.initial_feedback_operations o on o.operation_id=s.operation_id\n        where o.operation_id is null or o.state<>'published' or s.publication_id is distinct from o.publication_id\n          or (s.owner_id,s.organization_id,s.analysis_id,s.resume_id,s.resume_version_id,s.binding_sha256)\n            is distinct from (o.owner_id,o.organization_id,o.analysis_id,o.resume_id,o.resume_version_id,o.binding_sha256)\n          or exists(select 1 from private.initial_feedback_publications p where p.id=s.publication_id or p.operation_id=s.operation_id)\n          or s.publication_state not in ('assessed','deterministic_only') or not isfinite(s.retired_at)\n          or (s.publication_state='assessed' and (s.run_id is null or not exists(select 1 from private.initial_feedback_attempts t\n            where t.attempt_id=s.attempt_id and t.operation_id=o.operation_id and t.state='published' and t.error_code is null\n              and t.claimed_at is not null and isfinite(t.claimed_at) and t.usage is not null and private.ifo_usage_valid(t.usage))))\n          or (s.publication_state='deterministic_only' and s.run_id is not null)\n          or (s.attempt_id is not null and not exists(select 1 from private.initial_feedback_attempts t where t.attempt_id=s.attempt_id and t.operation_id=o.operation_id)))\n      and not exists(select 1 from private.initial_feedback_operations o where o.organization_id=a.organization_id and o.publication_id is not null\n        and not exists(select 1 from private.initial_feedback_publications p where p.id=o.publication_id and p.operation_id=o.operation_id\n          and p.owner_id=o.owner_id and p.organization_id=o.organization_id and p.analysis_id=o.analysis_id)\n        and not exists(select 1 from retirement_scope s where s.publication_id=o.publication_id and s.operation_id=o.operation_id\n          and s.owner_id=o.owner_id and s.organization_id=o.organization_id and s.analysis_id=o.analysis_id and s.binding_sha256=o.binding_sha256)) valid\n  ), legacy as (\n    select coalesce(sum(case when r.input_tokens>=0 and r.output_tokens>=0 then r.input_tokens::numeric+r.output_tokens::numeric else 0 end),0) tokens,\n      coalesce(bool_and(coalesce(r.input_tokens>=0 and r.output_tokens>=0,false)),true) valid\n    from public.analysis_ai_runs r where r.organization_id=a.organization_id\n      and r.created_at>=period_start::timestamp at time zone 'UTC' and r.created_at<period_end::timestamp at time zone 'UTC'\n      and not exists(select 1 from links l where l.run_id=r.id)\n  ), canonical as (\n    select coalesce(sum(case when x.usage is not null and private.ifo_usage_valid(x.usage) then\n      (x.usage->>'inputTokens')::numeric+(x.usage->>'outputTokens')::numeric else 0 end),0) tokens,\n      count(*) filter(where x.usage is null) unknown_count,\n      coalesce(bool_and(private.ifo_usage_valid(x.usage)),true) valid\n    from canonical_scope x where x.organization_id=a.organization_id\n      and x.claimed_at>=period_start::timestamp at time zone 'UTC' and x.claimed_at<period_end::timestamp at time zone 'UTC'\n  ), feedback as (\n    select coalesce(sum(case when x.usage is not null and private.ifo_usage_valid(x.usage) then\n      (x.usage->>'inputTokens')::numeric+(x.usage->>'outputTokens')::numeric else 0 end),0) tokens,\n      count(*) filter(where x.usage is null) unknown_count,\n      coalesce(bool_and(private.ifo_usage_valid(x.usage)),true) valid\n    from feedback_attempts x where x.claimed_at>=period_start::timestamp at time zone 'UTC'\n      and x.claimed_at<period_end::timestamp at time zone 'UTC'\n  ) select legacy.tokens,canonical.tokens,feedback.tokens,canonical.unknown_count+feedback.unknown_count,\n      legacy.valid and canonical.valid and feedback.valid,integrity.valid\n    into legacy_tokens,canonical_tokens,feedback_tokens,unknown_claims,values_valid,links_valid\n    from legacy cross join canonical cross join feedback cross join integrity;\n  if values_valid is not true or links_valid is not true or legacy_tokens is null or canonical_tokens is null or feedback_tokens is null\n    then perform private.ifo_fail('unavailable');end if;\n  total_tokens:=legacy_tokens+canonical_tokens+feedback_tokens;\n  if greatest(length(legacy_tokens::text),length(canonical_tokens::text),length(feedback_tokens::text),length(total_tokens::text))>128\n    then perform private.ifo_fail('unavailable');end if;\n  return jsonb_build_object('schemaVersion','initial-feedback-usage/1.0.0','profileVersion','initial-feedback-readiness-profile/1.0.0',\n    'usageSha256',(select encode(sha256(convert_to(prosrc,'UTF8')),'hex') from pg_catalog.pg_proc where oid=to_regprocedure('public.read_initial_feedback_usage(uuid,uuid)')),\n    'ownerId',p_user_id,'organizationId',a.organization_id,'analysisId',a.id,'periodStart',to_char(period_start,'YYYY-MM-DD'),'periodEnd',to_char(period_end,'YYYY-MM-DD'),\n    'legacyUnlinkedTokens',legacy_tokens::text,'canonicalTokens',canonical_tokens::text,'initialFeedbackTokens',feedback_tokens::text,\n    'totalTokens',total_tokens::text,'unknownClaims',unknown_claims::text);\nend;\n","new":"\ndeclare a public.analyses%rowtype;period_start date;period_end date;\n  legacy_tokens numeric;canonical_tokens numeric;feedback_tokens numeric;unknown_claims bigint;\n  values_valid boolean;links_valid boolean;total_tokens numeric;\nbegin\n  if private.initial_feedback_ready() is not true then perform private.ifo_fail('unavailable');end if;\n  a:=private.owned_ai_usage_owner(p_user_id,p_analysis_id);\n  period_start:=date_trunc('month',clock_timestamp() at time zone 'UTC')::date;\n  period_end:=(period_start+interval '1 month')::date;\n  if private.owned_legacy_ai_usage_ready() is not true then perform private.ifo_fail('unavailable');end if;\n  -- One statement snapshot; link validation/exclusion has NO month predicate.\n  -- Only the three disjoint components below select their respective month.\n  with preserved_integrity as materialized (select private.assert_owned_legacy_ai_usage_month(a.organization_id,period_start) proved), canonical_scope as materialized (\n    select x.owner_id,x.organization_id,x.analysis_id,x.operation_id,x.run_id,x.claimed_at,nullif(x.usage,'null'::jsonb) usage,\n      x.binding_sha256,x.policy->>'model' model,x.policy->>'promptVersion' prompt_version\n    from private.canonical_rewrite_operations x where x.organization_id=a.organization_id\n    union\n    select x.owner_id,x.organization_id,x.analysis_id,x.operation_id,x.run_id,x.claimed_at,nullif(x.usage,'null'::jsonb),\n      x.binding_sha256,x.policy->>'model',x.policy->>'promptVersion'\n    from private.canonical_rewrite_operations x join public.analysis_ai_runs r on r.id=x.run_id where r.organization_id=a.organization_id\n  ), feedback_attempts as materialized (\n    select t.attempt_id,t.operation_id,t.claimed_at,nullif(t.usage,'null'::jsonb) usage,o.owner_id,o.organization_id,o.analysis_id,\n      o.binding_sha256,o.binding->'policy'->>'model' model,o.binding->'policy'->>'promptVersion' prompt_version\n    from private.initial_feedback_attempts t join private.initial_feedback_operations o on o.operation_id=t.operation_id\n    where o.organization_id=a.organization_id\n  ), retirement_scope as materialized (\n    select s.* from private.initial_feedback_content_retirements s where s.organization_id=a.organization_id\n    union select s.* from private.initial_feedback_content_retirements s join private.initial_feedback_operations o on o.operation_id=s.operation_id where o.organization_id=a.organization_id\n    union select s.* from private.initial_feedback_content_retirements s join public.analysis_ai_runs r on r.id=s.run_id where r.organization_id=a.organization_id\n  ), publication_scope as materialized (\n    select p.id,p.operation_id,p.attempt_id,p.analysis_id,p.owner_id,p.organization_id,p.run_id,p.state,p.binding_sha256\n    from private.initial_feedback_publications p where p.organization_id=a.organization_id\n    union\n    select p.id,p.operation_id,p.attempt_id,p.analysis_id,p.owner_id,p.organization_id,p.run_id,p.state,p.binding_sha256\n    from private.initial_feedback_publications p join private.initial_feedback_operations o on o.operation_id=p.operation_id where o.organization_id=a.organization_id\n    union\n    select p.id,p.operation_id,p.attempt_id,p.analysis_id,p.owner_id,p.organization_id,p.run_id,p.state,p.binding_sha256\n    from private.initial_feedback_publications p join public.analysis_ai_runs r on r.id=p.run_id where r.organization_id=a.organization_id\n    union\n    select s.publication_id,s.operation_id,s.attempt_id,s.analysis_id,s.owner_id,s.organization_id,s.run_id,s.publication_state,s.binding_sha256\n    from retirement_scope s\n  ), links as materialized (\n    -- Retained pre-compatibility A12 legacy runs are authoritative links too.\n    select r.id run_id,coalesce(x.organization_id=a.organization_id and x.claimed_at is not null and isfinite(x.claimed_at)\n      and x.usage is not null and private.ifo_usage_valid(x.usage)\n      and (r.owner_id,r.organization_id,r.analysis_id)=(x.owner_id,x.organization_id,x.analysis_id)\n      and r.provider='openai' and r.model_id=x.model and r.prompt_version=x.prompt_version and r.input_hash=x.binding_sha256\n      and r.input_tokens>=0 and r.output_tokens>=0\n      and r.input_tokens::text=x.usage->>'inputTokens' and r.output_tokens::text=x.usage->>'outputTokens',false) valid\n    from canonical_scope x join public.analysis_ai_runs r on r.id=x.run_id\n    union all\n    select p.run_id,coalesce(p.organization_id=a.organization_id and p.state='assessed'\n      and o.operation_id=p.operation_id and o.publication_id=p.id and o.state='published'\n      and t.attempt_id=p.attempt_id and t.operation_id=o.operation_id\n      and (p.owner_id,p.organization_id,p.analysis_id)=(o.owner_id,o.organization_id,o.analysis_id)\n      and p.binding_sha256=o.binding_sha256 and t.claimed_at is not null and isfinite(t.claimed_at)\n      and nullif(t.usage,'null'::jsonb) is not null and private.ifo_usage_valid(t.usage)\n      and (r.owner_id,r.organization_id,r.analysis_id)=(p.owner_id,p.organization_id,p.analysis_id)\n      and r.provider='openai' and r.model_id=o.binding->'policy'->>'model' and r.prompt_version=o.binding->'policy'->>'promptVersion'\n      and r.input_hash=o.binding_sha256 and r.input_tokens>=0 and r.output_tokens>=0\n      and r.input_tokens::text=t.usage->>'inputTokens' and r.output_tokens::text=t.usage->>'outputTokens',false)\n    from publication_scope p left join private.initial_feedback_operations o on o.operation_id=p.operation_id\n      left join private.initial_feedback_attempts t on t.attempt_id=p.attempt_id\n      left join public.analysis_ai_runs r on r.id=p.run_id where p.run_id is not null\n      and (r.id is not null or not exists(select 1 from retirement_scope s where s.publication_id=p.id and s.run_id=p.run_id))\n  ), integrity as (\n    select not exists(select 1 from links where not valid)\n      and not exists(select 1 from links group by run_id having count(*)>1)\n      and not exists(select 1 from retirement_scope s left join private.initial_feedback_operations o on o.operation_id=s.operation_id\n        where o.operation_id is null or o.state<>'published' or s.publication_id is distinct from o.publication_id\n          or (s.owner_id,s.organization_id,s.analysis_id,s.resume_id,s.resume_version_id,s.binding_sha256)\n            is distinct from (o.owner_id,o.organization_id,o.analysis_id,o.resume_id,o.resume_version_id,o.binding_sha256)\n          or exists(select 1 from private.initial_feedback_publications p where p.id=s.publication_id or p.operation_id=s.operation_id)\n          or s.publication_state not in ('assessed','deterministic_only') or not isfinite(s.retired_at)\n          or (s.publication_state='assessed' and (s.run_id is null or not exists(select 1 from private.initial_feedback_attempts t\n            where t.attempt_id=s.attempt_id and t.operation_id=o.operation_id and t.state='published' and t.error_code is null\n              and t.claimed_at is not null and isfinite(t.claimed_at) and t.usage is not null and private.ifo_usage_valid(t.usage))))\n          or (s.publication_state='deterministic_only' and s.run_id is not null)\n          or (s.attempt_id is not null and not exists(select 1 from private.initial_feedback_attempts t where t.attempt_id=s.attempt_id and t.operation_id=o.operation_id)))\n      and not exists(select 1 from private.initial_feedback_operations o where o.organization_id=a.organization_id and o.publication_id is not null\n        and not exists(select 1 from private.initial_feedback_publications p where p.id=o.publication_id and p.operation_id=o.operation_id\n          and p.owner_id=o.owner_id and p.organization_id=o.organization_id and p.analysis_id=o.analysis_id)\n        and not exists(select 1 from retirement_scope s where s.publication_id=o.publication_id and s.operation_id=o.operation_id\n          and s.owner_id=o.owner_id and s.organization_id=o.organization_id and s.analysis_id=o.analysis_id and s.binding_sha256=o.binding_sha256)) valid\n  ), legacy as (\n    select coalesce(sum(case when r.input_tokens>=0 and r.output_tokens>=0 then r.input_tokens::numeric+r.output_tokens::numeric else 0 end),0) tokens,\n      coalesce(bool_and(coalesce(r.input_tokens>=0 and r.output_tokens>=0,false)),true) valid\n    from public.analysis_ai_runs r where r.organization_id=a.organization_id\n      and r.created_at>=period_start::timestamp at time zone 'UTC' and r.created_at<period_end::timestamp at time zone 'UTC'\n      and not exists(select 1 from links l where l.run_id=r.id)\n  ), canonical as (\n    select coalesce(sum(case when x.usage is not null and private.ifo_usage_valid(x.usage) then\n      (x.usage->>'inputTokens')::numeric+(x.usage->>'outputTokens')::numeric else 0 end),0) tokens,\n      count(*) filter(where x.usage is null) unknown_count,\n      coalesce(bool_and(private.ifo_usage_valid(x.usage)),true) valid\n    from canonical_scope x where x.organization_id=a.organization_id\n      and x.claimed_at>=period_start::timestamp at time zone 'UTC' and x.claimed_at<period_end::timestamp at time zone 'UTC'\n  ), feedback as (\n    select coalesce(sum(case when x.usage is not null and private.ifo_usage_valid(x.usage) then\n      (x.usage->>'inputTokens')::numeric+(x.usage->>'outputTokens')::numeric else 0 end),0) tokens,\n      count(*) filter(where x.usage is null) unknown_count,\n      coalesce(bool_and(private.ifo_usage_valid(x.usage)),true) valid\n    from feedback_attempts x where x.claimed_at>=period_start::timestamp at time zone 'UTC'\n      and x.claimed_at<period_end::timestamp at time zone 'UTC'\n  ) select legacy.tokens+(select coalesce(sum(t.input_tokens::numeric+t.output_tokens::numeric),0) from private.owned_legacy_ai_usage_retirements t\n      where t.organization_id=a.organization_id and t.classification='legacy_unlinked' and t.original_month=period_start\n        and not exists(select 1 from public.analysis_ai_runs r where r.id=t.run_id)),canonical.tokens,feedback.tokens,canonical.unknown_count+feedback.unknown_count,\n      legacy.valid and canonical.valid and feedback.valid,integrity.valid\n    into legacy_tokens,canonical_tokens,feedback_tokens,unknown_claims,values_valid,links_valid\n    from legacy cross join canonical cross join feedback cross join integrity cross join preserved_integrity where preserved_integrity.proved;\n  if values_valid is not true or links_valid is not true or legacy_tokens is null or canonical_tokens is null or feedback_tokens is null\n    then perform private.ifo_fail('unavailable');end if;\n  total_tokens:=legacy_tokens+canonical_tokens+feedback_tokens;\n  if greatest(length(legacy_tokens::text),length(canonical_tokens::text),length(feedback_tokens::text),length(total_tokens::text))>128\n    then perform private.ifo_fail('unavailable');end if;\n  return jsonb_build_object('schemaVersion','initial-feedback-usage/1.0.0','profileVersion','initial-feedback-readiness-profile/1.0.0',\n    'usageSha256',(select encode(sha256(convert_to(prosrc,'UTF8')),'hex') from pg_catalog.pg_proc where oid=to_regprocedure('public.read_initial_feedback_usage(uuid,uuid)')),\n    'ownerId',p_user_id,'organizationId',a.organization_id,'analysisId',a.id,'periodStart',to_char(period_start,'YYYY-MM-DD'),'periodEnd',to_char(period_end,'YYYY-MM-DD'),\n    'legacyUnlinkedTokens',legacy_tokens::text,'canonicalTokens',canonical_tokens::text,'initialFeedbackTokens',feedback_tokens::text,\n    'totalTokens',total_tokens::text,'unknownClaims',unknown_claims::text);\nend;\n","setof":false},{"signature":"private.owned_ai_retirement_ready()","before":"5beec572fc142c904c1dc7282d5da5fbae844818126089a07085da267ecc6aaf","after":"a0b6290511973757a983b793f249c8ef1225091eaac5a118847a7e4bb53d0694","old":"\ndeclare item jsonb;p pg_catalog.pg_proc%rowtype;owner_oid oid;service_oid oid;role_name text;rel pg_catalog.pg_class%rowtype;col jsonb;expected smallint[];\n manifest jsonb:=$retirement_catalog$[{\"signature\":\"private.owned_ai_retirement_guard()\",\"sha256\":\"8cbbd706652a3f41eb39db83da3a34757557950bd06364d4b5741fd